@startuml

class Airline {
  + Name : string
  + ParentAirline : Airline
}

class Employee {
  + Name : string
  + StartDate : date
}

class Salesperson {
  + EmployeeId : int
}

class Contract {
  + Number : int
  + DeliveryConditions : string
  + LegalAspects : string
  + SalespersonId : int
}

class AircraftAcquisition {
  + ContractNumber : int
  + Model : string
  + Price : double
  + Options : string
  + Customizations : string
  + DeliveryDate : date
}

Airline "0..1" -- "0..*" Airline
Employee "0..*" -- "0..*" Salesperson
Salesperson "0..*" -- "0..*" Contract
Contract "1" -- "0..*" AircraftAcquisition

@enduml

